package com.foodieexpress.service;
import com.foodieexpress.model.*;import com.foodieexpress.repository.*;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class WishlistServiceTest {
 private WishlistItemRepository wishlist;private FoodItemRepository foods;private WishlistService service;
 @BeforeEach void setup(){wishlist=mock(WishlistItemRepository.class);foods=mock(FoodItemRepository.class);service=new WishlistService(wishlist,foods);}
 private Customer customer(long id){return Customer.builder().id(id).fullName("Customer"+id).build();}
 @Test void addIsIdempotentForAnExistingFavourite(){Customer c=customer(1);Restaurant r=Restaurant.builder().id(9L).name("Kitchen").active(true).rating(4.6).build();FoodItem food=FoodItem.builder().id(5L).name("Curry").price(new BigDecimal("150.00")).imagePath("/images/curry.jpg").restaurant(r).available(true).build();WishlistItem saved=WishlistItem.builder().id(7L).customer(c).foodItemId(5L).createdAt(LocalDateTime.now()).build();when(foods.findById(5L)).thenReturn(Optional.of(food));when(wishlist.findByCustomerAndFoodItemId(c,5L)).thenReturn(Optional.of(saved));var result=service.add(c,5L);assertThat(result.id()).isEqualTo(7L);assertThat(result.available()).isTrue();verify(wishlist,never()).save(any());}
 @Test void wishlistQueryIsScopedToTheRequestedCustomerAndUnavailableDishIsRetained(){Customer c=customer(2);WishlistItem saved=WishlistItem.builder().id(4L).customer(c).foodItemId(99L).savedName("Old dish").savedPrice(new BigDecimal("99.00")).createdAt(LocalDateTime.now()).build();when(wishlist.findByCustomerOrderByCreatedAtDesc(c)).thenReturn(List.of(saved));when(foods.findAllById(List.of(99L))).thenReturn(List.of());var result=service.get(c);verify(wishlist).findByCustomerOrderByCreatedAtDesc(c);assertThat(result).hasSize(1);assertThat(result.get(0).name()).isEqualTo("Old dish");assertThat(result.get(0).removed()).isTrue();assertThat(result.get(0).available()).isFalse();}
 @Test void unavailableFoodIsReportedWithoutLosingItsCurrentData(){Customer c=customer(1);Restaurant r=Restaurant.builder().id(2L).name("Kitchen").active(false).rating(4.2).build();FoodItem food=FoodItem.builder().id(5L).name("Curry").price(new BigDecimal("150.00")).restaurant(r).available(true).build();WishlistItem saved=WishlistItem.builder().id(7L).customer(c).foodItemId(5L).createdAt(LocalDateTime.now()).build();when(wishlist.findByCustomerOrderByCreatedAtDesc(c)).thenReturn(List.of(saved));when(foods.findAllById(List.of(5L))).thenReturn(List.of(food));var result=service.get(c).get(0);assertThat(result.name()).isEqualTo("Curry");assertThat(result.available()).isFalse();assertThat(result.removed()).isFalse();}
 @Test void removeDeletesOnlyTheCurrentCustomerEntry(){Customer c=customer(6);when(wishlist.deleteByCustomerAndFoodItemId(c,13L)).thenReturn(1L);service.remove(c,13L);verify(wishlist).deleteByCustomerAndFoodItemId(c,13L);}
 @Test void removeReportsMissingFavourite(){when(wishlist.deleteByCustomerAndFoodItemId(any(),anyLong())).thenReturn(0L);assertThatThrownBy(()->service.remove(customer(6),13L)).hasMessageContaining("Favourite not found");}
}
